package com.lingdong.learning.student.application;
import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.assertj.core.api.Assertions.*;
import com.lingdong.learning.student.infrastructure.persistence.*;import com.lingdong.learning.student.domain.Student;
import com.lingdong.learning.organization.infrastructure.persistence.OrganizationMapper;import com.lingdong.learning.organization.domain.Organization;
import com.lingdong.learning.feature.application.FeatureAccessService;import com.lingdong.learning.auth.application.AuthenticatedUser;import com.lingdong.learning.auth.domain.AuthClientType;import com.lingdong.learning.datascope.application.OrganizationDataScope;import java.util.*;
class StudentNumberRulesTest {
 final AcademicMetadataStore store=mock(AcademicMetadataStore.class);final StudentManagementAccessService access=mock(StudentManagementAccessService.class);final OrganizationMapper orgs=mock(OrganizationMapper.class);final StudentMapper students=mock(StudentMapper.class);final StudentOrganizationMapper relations=mock(StudentOrganizationMapper.class);final FeatureAccessService features=mock(FeatureAccessService.class);
 final StudentNumberService service=new StudentNumberService(store,access,orgs,students,relations,features);final AuthenticatedUser actor=new AuthenticatedUser(1L,2L,"actor","actor",AuthClientType.MINIAPP,List.of());final OrganizationDataScope scope=new OrganizationDataScope(false,false,List.of("/2/"));
 StudentNumberRulesTest(){var student=Student.create(10L,"child",null,11L);when(students.findById(10L)).thenReturn(student);when(students.findByIdForUpdate(10L)).thenReturn(student);var school=Organization.create(2L,null,"ROOT","S","school","SCHOOL","/2/",1,null);when(orgs.findById(2L)).thenReturn(school);when(orgs.findByIdForUpdate(2L)).thenReturn(school);when(access.scope(actor)).thenReturn(scope);when(relations.findActiveOrganizationIdsForUpdate(10L)).thenReturn(List.of(2L));when(relations.existsActiveEnrollmentInScope(10L,2L,scope)).thenReturn(true);}
 @Test void exactEnrollmentScopeIsRequiredForReadAndWrite(){when(relations.existsActiveEnrollmentInScope(10L,2L,scope)).thenReturn(false);assertThatThrownBy(()->service.read(actor,10L,2L)).isInstanceOf(com.lingdong.learning.common.web.ResourceNotFoundException.class);assertThatThrownBy(()->service.update(actor,10L,2L,"A1",0)).isInstanceOf(com.lingdong.learning.common.web.ResourceNotFoundException.class);verifyNoInteractions(store);}
 @Test void missingLockedEnrollmentCannotWrite(){when(relations.findActiveOrganizationIdsForUpdate(10L)).thenReturn(List.of(99L));assertThatThrownBy(()->service.update(actor,10L,2L,"A1",0)).isInstanceOf(com.lingdong.learning.common.web.ResourceNotFoundException.class);verifyNoInteractions(store);}
 @Test void absentMetadataIsNotInvented(){when(store.enrollmentMetadata(10L,2L)).thenReturn(Optional.empty());var result=service.read(actor,10L,2L);assertThat(result.studentNumber()).isNull();assertThat(result.versionNo()).isZero();}
 @Test void trimmedNumberCreatesOnlyExactEnrollment(){when(store.enrollmentMetadata(10L,2L)).thenReturn(Optional.empty(),Optional.of(new AcademicMetadataStore.EnrollmentMetadata(10L,2L,"A1",1)));assertThat(service.update(actor,10L,2L," A1 ",0).studentNumber()).isEqualTo("A1");verify(store).insertEnrollment(10L,2L,"A1");}
 @Test void invalidNumbersNeverReachStore(){for(String number:List.of("   ","x".repeat(65),"a\nb"))assertThatThrownBy(()->service.update(actor,10L,2L,number,0)).isInstanceOf(IllegalArgumentException.class);verifyNoInteractions(store);}
 @Test void staleVersionCannotOverwrite(){when(store.enrollmentMetadata(10L,2L)).thenReturn(Optional.of(new AcademicMetadataStore.EnrollmentMetadata(10L,2L,"A1",2)));assertThatThrownBy(()->service.update(actor,10L,2L,"A2",1)).isInstanceOf(IllegalStateException.class);verify(store,never()).updateEnrollment(anyLong(),anyLong(),any(),anyInt());}
 @Test void nullExplicitlyClearsNumber(){when(store.enrollmentMetadata(10L,2L)).thenReturn(Optional.of(new AcademicMetadataStore.EnrollmentMetadata(10L,2L,"A1",1)),Optional.of(new AcademicMetadataStore.EnrollmentMetadata(10L,2L,null,2)));when(store.updateEnrollment(10L,2L,null,1)).thenReturn(true);assertThat(service.update(actor,10L,2L,null,1).studentNumber()).isNull();}
 @Test void duplicateNumberBecomesConflict(){when(store.enrollmentMetadata(10L,2L)).thenReturn(Optional.empty());doThrow(new org.springframework.dao.DuplicateKeyException("fixture")).when(store).insertEnrollment(10L,2L,"A1");assertThatThrownBy(()->service.update(actor,10L,2L,"A1",0)).isInstanceOf(IllegalStateException.class).hasMessageContaining("已被使用");}
 @Test void globalSwitchStopsAccessBeforeResources(){doThrow(new com.lingdong.learning.feature.application.FeatureDisabledException("STUDENT_ORGANIZATION_RELATIONSHIP")).when(features).requireEnabled("STUDENT_ORGANIZATION_RELATIONSHIP",null);assertThatThrownBy(()->service.read(actor,10L,2L)).isInstanceOf(com.lingdong.learning.feature.application.FeatureDisabledException.class);assertThatThrownBy(()->service.update(actor,10L,2L,"A1",0)).isInstanceOf(com.lingdong.learning.feature.application.FeatureDisabledException.class);verifyNoInteractions(store,students,orgs,relations);}
 @Test void localInstitutionSwitchStopsMetadataReadsAndWrites(){doThrow(new com.lingdong.learning.feature.application.FeatureDisabledException("STUDENT_ORGANIZATION_RELATIONSHIP")).when(features).requireEnabled("STUDENT_ORGANIZATION_RELATIONSHIP",2L);assertThatThrownBy(()->service.read(actor,10L,2L)).isInstanceOf(com.lingdong.learning.feature.application.FeatureDisabledException.class);assertThatThrownBy(()->service.update(actor,10L,2L,"A1",0)).isInstanceOf(com.lingdong.learning.feature.application.FeatureDisabledException.class);verifyNoInteractions(store);}
}
